@net.neoforged.neoforge.gametest.PrefixGameTestTemplate(false)
public final class SolarSystemGameTests {
 @GameTest(template="empty",templateNamespace="around_planet",batch="solarWarp",timeoutTicks=120)
 public static void warpPersistsTerminalContactAndKeepsEarthCoordinates(GameTestHelper h){var sys=new CelestialSystem(20000,4e9,0);var data=new SpaceOrbitData();data.system(sys);var id=UUID.randomUUID();var other=UUID.randomUUID();double radius=sys.solarDestructionRadius()*2;data.put(id,new SpaceTrajectory(CelestialSystem.SUN,0,new SpaceState(new SpaceVector(radius,0,0),new SpaceVector(-2000,10,0)),sys.sunMu()));var local=new SpaceTrajectory(CelestialSystem.EARTH,0,new SpaceState(new SpaceVector(40000,0,0),new SpaceVector(0,Math.sqrt(sys.earthMu()/40000),0)),sys.earthMu());data.put(other,local);data.warp(0,1000000);h.assertTrue(data.solarImpacts().contains(id),"Warp skipped photosphere contact");h.assertTrue(data.sample(id,0).position().length()<=sys.solarDestructionRadius()+1,"Warp propagated through Sun");h.assertTrue(data.sample(other,0).position().subtract(local.at(1000000).position()).length()<1e-7,"Earth-local coast changed with heliocentric origin");var saved=data.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var restored=SpaceOrbitData.load(saved,h.getLevel().registryAccess());h.assertTrue(restored.solarImpacts().contains(id),"Restart forgot terminal contact");h.succeed();}
 @GameTest(template="empty",templateNamespace="around_planet",batch="solarCoast",timeoutTicks=120)
 public static void solarCoastCannotReturnToEarthOrAcquireAtmosphericDrag(GameTestHelper h){var l=h.getLevel();var data=SpaceOrbitData.get(l.getServer());var id=UUID.randomUUID();var old=data.system();var cells=SpaceCells.get(l);var cell=new SpaceCells.Cell(id,74,28000,9000,0,0,2200,0,List.of(UUID.randomUUID()));try{var planet=new PlanetScale(131072).geometry();var sys=new CelestialSystem(planet.radius(),9.81*planet.radius()*planet.radius(),0);data.system(sys);double r=sys.sunRadius()*3;var path=new SpaceTrajectory(CelestialSystem.SUN,l.getGameTime(),new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(sys.sunMu()/r),0)),sys.sunMu());data.put(id,path);data.navigate(id,new SpaceNavigation(planet,SpaceFrame.IDENTITY));cells.add(l,cell);var c=SubLevelContainer.getContainer(l);SpaceAtmosphere.advance(l,id,cell);SpaceReentry.check(l,c,new HashSet<>(List.of(id)),new HashMap<>());SpaceUnloadedImpact.check(l,c);h.assertTrue(data.get(id).orElseThrow().equals(path)&&data.reentry(id).isEmpty(),"Solar orbit was treated as an Earth descent");var observer=net.neoforged.neoforge.common.util.FakePlayerFactory.get(l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"SolarReadout"));observer.setPos(cell.x(),cell.y(),cell.z());var packet=SpaceTelemetry.sample(observer);h.assertTrue(packet.primary().equals(CelestialSystem.SUN)&&packet.radius()==sys.sunRadius()&&packet.returnAltitude()==sys.solarDestructionRadius()-sys.sunRadius()&&packet.mu()==sys.sunMu(),"Telemetry retained Earth radius/atmosphere in solar space");h.succeed();}finally{data.system(old);data.remove(id);cells.remove(l,cell);SpaceAtmosphere.forget(l,id);}}
 @GameTest(template="empty",templateNamespace="around_planet",batch="solarFrames",timeoutTicks=120)
 public static void primaryTransitionsPreserveNativePoseAndPointVelocity(GameTestHelper h){h.runAfterDelay(3,()->{var l=h.getLevel();var c=SubLevelContainer.getContainer(l);var p=h.absolutePos(new BlockPos(1,2,1));l.setBlockAndUpdate(p,Blocks.IRON_BLOCK.defaultBlockState());var ship=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY(),p.getZ()));var data=SpaceOrbitData.get(l.getServer());var old=data.system();var id=UUID.randomUUID();try{var sys=new CelestialSystem(20000,4e9,123);data.system(sys);long now=l.getGameTime();var state=new SpaceState(new SpaceVector(sys.earthSoi()+1,0,0),new SpaceVector(350,20,4));data.put(id,new SpaceTrajectory(CelestialSystem.EARTH,now,state,sys.earthMu()));var point=new Vector3d(ship.logicalPose().position());var velocity=c.physicsSystem().getPipeline().getLinearVelocity(ship,new Vector3d());CelestialRuntime.advance(l,data);var solar=data.get(id).orElseThrow();h.assertTrue(solar.primary().equals(CelestialSystem.SUN),"No Earth escape");var absolute=sys.global(CelestialSystem.EARTH,state,now);h.assertTrue(solar.at(now).position().subtract(absolute.position()).length()<1e-7&&solar.at(now).velocity().subtract(absolute.velocity()).length()<1e-7,"Earth velocity was lost or applied twice");var local=new SpaceState(new SpaceVector(40000,0,0),new SpaceVector(0,-250,0));data.put(id,new SpaceTrajectory(CelestialSystem.SUN,now,sys.global(CelestialSystem.EARTH,local,now),sys.sunMu()));CelestialRuntime.advance(l,data);h.assertTrue(data.get(id).orElseThrow().primary().equals(CelestialSystem.EARTH),"No moving Earth entry");h.assertTrue(data.sample(id,now).velocity().subtract(local.velocity()).length()<1e-7,"Earth entry retained solar translation");h.assertTrue(ship.logicalPose().position().distance(point)<1e-8&&c.physicsSystem().getPipeline().getLinearVelocity(ship,new Vector3d()).distance(velocity)<1e-8,"SOI transition teleported or accelerated native body");h.succeed();}finally{data.remove(id);data.system(old);if(!ship.isRemoved())c.removeSubLevel(ship,SubLevelRemovalReason.REMOVED);}});}
 @GameTest(template="empty",templateNamespace="around_planet",batch="solarImpact",timeoutTicks=160)
 public static void solarImpactDeletesAwakeHeldAndFreeBodiesButPreservesUnrelatedCargo(GameTestHelper h){h.runAfterDelay(3,()->{var l=h.getLevel();var c=SubLevelContainer.getContainer(l);var data=SpaceOrbitData.get(l.getServer());var cells=SpaceCells.get(l);var cargo=SpaceCargoData.get(l.getServer());var id=UUID.randomUUID();var ids=new ArrayList<UUID>();var old=data.system();var chunk=new ChunkPos(1812,0);SpaceCells.Cell cell=null;net.neoforged.neoforge.common.util.FakePlayer player=null,plotPlayer=null;try{
  for(int i=0;i<4;i++){var p=h.absolutePos(new BlockPos(1+i*2,2,1));l.setBlockAndUpdate(p,Blocks.IRON_BLOCK.defaultBlockState());var ship=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY(),p.getZ()));ids.add(ship.getUniqueId());c.physicsSystem().getPipeline().teleport(ship,new Vector3d(i==3?34000:30000+i*4,9000,0),ship.logicalPose().orientation());ship.updateBoundingBox();ship.updateLastPose();}
  cell=new SpaceCells.Cell(id,75,30000,9000,0,0,2200,0,List.of(ids.get(0),ids.get(1)));cells.add(l,cell);var planet=new PlanetScale(131072).geometry();var sys=new CelestialSystem(planet.radius(),9.81*planet.radius()*planet.radius(),0);data.system(sys);data.navigate(id,new SpaceNavigation(planet,SpaceFrame.IDENTITY));data.put(id,new SpaceTrajectory(CelestialSystem.SUN,l.getGameTime(),new SpaceState(new SpaceVector(sys.solarDestructionRadius()-1,0,0),new SpaceVector(-100,0,0)),0));
  c.getHoldingChunkMap().moveToUnloaded((ServerSubLevel)c.getSubLevel(ids.get(1)),chunk);c.getHoldingChunkMap().moveToUnloaded((ServerSubLevel)c.getSubLevel(ids.get(3)),chunk);h.assertTrue(cargo.all().stream().anyMatch(r->r.ship().equals(ids.get(1))),"No held cargo address");
  player=new net.neoforged.neoforge.common.util.FakePlayer(l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"SolarVictim"));try{var field=net.minecraft.network.Connection.class.getDeclaredField("channel");field.setAccessible(true);field.set(player.connection.getConnection(),new io.netty.channel.embedded.EmbeddedChannel());}catch(ReflectiveOperationException e){throw new AssertionError(e);}player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(30000,9002,0);l.addNewPlayer(player);var plot=c.getSubLevel(ids.get(0)).getPlot().getCenterBlock();plotPlayer=fixturePlayer(l,"SolarPlotVictim",plot.getX()+.5,plot.getY()+1,plot.getZ()+.5);CelestialRuntime.advance(l,data);h.assertTrue(data.solarImpacts().contains(id),"Runtime missed solar contact");SpaceSolarImpact.check(l,c);
  h.assertTrue(player.isDeadOrDying()&&plotPlayer.isDeadOrDying(),"World/plot player survived solar destruction");for(int i=0;i<3;i++){h.assertTrue(c.getSubLevel(ids.get(i))==null&&c.getHoldingChunkMap().getHoldingSubLevel(ids.get(i))==null,"Solar body survived: "+i);h.assertTrue(cargo.all().stream().noneMatch(r->r.ship().equals(ids.get(1))),"Cargo record survived");}h.assertTrue(c.getHoldingChunkMap().getHoldingSubLevel(ids.get(3))!=null,"Unrelated held body was deleted");h.assertTrue(data.get(id).isEmpty()&&!data.solarImpacts().contains(id)&&cells.forShip(ids.get(0))==null,"Solar space/orbit survived");h.succeed();
 }finally{if(player!=null)l.removePlayerImmediately(player,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);if(plotPlayer!=null)l.removePlayerImmediately(plotPlayer,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);if(cell!=null)cells.remove(l,cell);data.remove(id);data.system(old);for(var nativeId:ids){cargo.remove(nativeId);var ship=c.getSubLevel(nativeId);if(ship!=null)c.removeSubLevel(ship,SubLevelRemovalReason.REMOVED);else((SpaceHoldingAccess)c.getHoldingChunkMap()).around_planet$discard(nativeId,chunk);}}});}
 @GameTest(template="empty",templateNamespace="around_planet",batch="solarYear",timeoutTicks=120)
 public static void customYearSurvivesSaveWarpAndAllCelestialPackets(GameTestHelper h){
  var sys=new CelestialSystem(20000,4e9,123,2000,240000);var data=new SpaceOrbitData();data.system(sys);
  var tag=data.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var restored=SpaceOrbitData.load(tag,h.getLevel().registryAccess());h.assertTrue(sys.equals(restored.system()),"Custom year lost on save/load");restored.warp(0,1000);h.assertTrue(restored.system().yearSeconds()==sys.yearSeconds(),"Warp lost custom year");
  tag.getCompound("celestialSystem").remove("yearSeconds");h.assertTrue(SpaceOrbitData.load(tag,h.getLevel().registryAccess()).system().yearSeconds()==0,"Old save lost legacy year");
  var path=new SpaceTrajectory(CelestialSystem.EARTH,0,new SpaceState(new SpaceVector(40000,0,0),new SpaceVector(0,300,0)),sys.earthMu());
  var sky=new io.github.astelev.around_planet.network.CelestialSkyPayload(sys);
  roundTrip(h,io.github.astelev.around_planet.network.CelestialSkyPayload.CODEC,sky);
  var status=new io.github.astelev.around_planet.network.SpaceStatusPayload(true,40000,0,0,0,300,0,20000,false,20000,4e9,2000,4000,SpaceFrame.IDENTITY,SpaceVector.ZERO,CelestialSystem.EARTH,sys);
  roundTrip(h,io.github.astelev.around_planet.network.SpaceStatusPayload.CODEC,status);
  var plan=new io.github.astelev.around_planet.network.ManeuverPayload(UUID.randomUUID(),0,path,List.of(),UUID.randomUUID(),0,true,"",30,sys,6,1);
  roundTrip(h,io.github.astelev.around_planet.network.ManeuverPayload.CODEC,plan);h.succeed();
 }
 private static <T> void roundTrip(GameTestHelper h,net.minecraft.network.codec.StreamCodec<net.minecraft.network.RegistryFriendlyByteBuf,T> codec,T packet){var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{codec.encode(b,packet);h.assertTrue(codec.decode(b).equals(packet)&&b.readableBytes()==0,"Celestial packet did not round-trip completely");}finally{b.release();}}
 private static net.neoforged.neoforge.common.util.FakePlayer fixturePlayer(net.minecraft.server.level.ServerLevel l,String name,double x,double y,double z){var p=new net.neoforged.neoforge.common.util.FakePlayer(l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),name));try{var field=net.minecraft.network.Connection.class.getDeclaredField("channel");field.setAccessible(true);field.set(p.connection.getConnection(),new io.netty.channel.embedded.EmbeddedChannel());}catch(ReflectiveOperationException e){throw new AssertionError(e);}p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setPos(x,y,z);l.addNewPlayer(p);return p;}

}
